 {module==='plans'&&<div className="form-grid"><Field label="Loại kế hoạch" value={form.type||'TUẦN'} onChange={x=>change('type',x)}><select value={form.type||'TUẦN'} onChange={e=>change('type',e.target.value)}><option>TUẦN</option><option>THÁNG</option></select></Field><Field label="Từ ngày" value={form.fromDate} type="date" onChange={x=>change('fromDate',x)} required/><Field label="Đến ngày" value={form.toDate} type="date" onChange={x=>change('toDate',x)} required/><Field label="Bộ phận" value={form.department} onChange={x=>change('department',x)}><select value={form.department||''} onChange={e=>change('department',e.target.value)}><option value="">Chọn bộ phận</option>{allDepartments.map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Nội dung kế hoạch" value={form.content} onChange={x=>change('content',x)} wide required/><Field label="Nội dung / Mô tả" value={form.description} onChange={x=>change('description',x)} wide><textarea rows={4} value={form.description||''} onChange={e=>change('description',e.target.value)}/></Field><Field label="Người phụ trách" value={form.owner} onChange={x=>change('owner',x)}><select value={form.owner||''} onChange={e=>change('owner',e.target.value)}><option value="">Chọn nhân viên</option>{staff.map(x=><option key={x.name}>{x.name}</option>)}</select></Field><Field label="Trạng thái" value={form.status||'CHƯA BẮT ĐẦU'} onChange={x=>change('status',x)}/><Field label="Kết quả" value={form.result} onChange={x=>change('result',x)} wide/><Field label="Ghi chú" value={form.note} onChange={x=>change('note',x)} wide><textarea rows={3} value={form.note||''} onChange={e=>change('note',e.target.value)}/></Field></div>}
